class VoidBrowserController {
  Future<void> Function(String path)? _scrollToTrack;
  bool Function(String path)? _isTrackVisible;

  /// Centre the row for [path] in view; no-op when the browser is unmounted.
  Future<void> scrollToTrack(String path) async =>
      await _scrollToTrack?.call(path);

  /// Whether the row for [path] is currently inside the browser's visible
  /// scroll viewport.
  ///
  /// When the browser isn't mounted / can't measure yet, this defaults to
  /// `true` so callers don't surface an action prematurely.
  bool isTrackVisible(String path) => _isTrackVisible?.call(path) ?? true;
}

